package com.example.partnerintegrationmock.api;
import com.example.partnerintegrationmock.application.MockBookingService.*; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(Missing.class) ProblemDetail missing(RuntimeException e){return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND,e.getMessage());} @ExceptionHandler(Conflict.class) ProblemDetail conflict(RuntimeException e){return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT,e.getMessage());} @ExceptionHandler(MethodArgumentNotValidException.class) ProblemDetail bad(Exception e){return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,"Invalid booking request");} }
